CREATE OR REPLACE FUNCTION scalius_compat."cdep_promotion_redemptions_ins_fn"()
RETURNS trigger
LANGUAGE plpgsql
AS $trigger_function$
BEGIN
  IF NOT coalesce((EXISTS (SELECT 1 FROM promotions WHERE promotions.id = NEW.promotion_id AND (promotions.max_redemptions IS NOT NULL OR promotions.max_discount_spend_minor IS NOT NULL))), false) THEN
    RETURN NULL;
  END IF;
  PERFORM scalius_compat."cache_dep_bump"(ARRAY(SELECT key_list.value AS dep FROM unnest(ARRAY['promo:' || NEW."promotion_id", 't:promotion_redemptions']::text[]) AS key_list(value)));
  RETURN NULL;
END
